import sys
D='/home/user/wt/lot-053/Claude/LOT_053/_travail/DX.3/src/'
def patch(f,pairs):
    p=D+f; s=open(p,encoding='utf8').read()
    for a,b in pairs:
        if a not in s: print('MISS',f,a[:70]); continue
        s=s.replace(a,b,1)
    open(p,'w',encoding='utf8').write(s)
